import { useStudio } from '../../internal/extensions';
import { buildTransaction } from './TransactionQueue/buildTransaction';
import { transactionsScope } from './types';
import { vitePluginEnabled } from './vitePluginEnabled';
export const useTransactions = () => {
    const { useExtension } = useStudio();
    const ext = useExtension(transactionsScope);
    const onTransaction = (...args) => {
        return ext.state.queue?.onTransaction(...args);
    };
    const onCommit = (...args) => {
        return ext.state.queue?.onCommit(...args);
    };
    const onUndo = (...args) => {
        return ext.state.queue?.onUndo(...args);
    };
    const onRedo = (...args) => {
        return ext.state.queue?.onRedo(...args);
    };
    return {
        commit: ext.commit,
        undo: ext.undo,
        redo: ext.redo,
        onTransaction,
        onCommit,
        onUndo,
        onRedo,
        openInEditor: ext.openInEditor,
        openSelectedInEditor: ext.openSelectedInEditor,
        buildTransaction,
        vitePluginEnabled
    };
};
